import { verifyPackageDirectory } from './package-signing';
import { RELEASE_VERSION } from '../shared/version';

// The uninstaller is generated by NSIS after the application payload is signed.
export const distributionFileExcluded = (relative: string) =>
  /^Uninstall Blode Studio\.exe$/i.test(relative) || relative.split('/').at(-1) === '.uel';

export async function verifyDistribution(directory: string) {
  const result = await verifyPackageDirectory(
    directory,
    { kind: 'application', id: 'Blode.Studio.Protected', version: RELEASE_VERSION },
    { exclude: distributionFileExcluded },
  );
  if (result.status !== 'verified') throw new Error('安装文件校验失败，请重新安装。');
  return result;
}
